void require(bool value,const char* message) {if(!value) throw std::runtime_error(message);}
void put(net::Packet& p,std::uint64_t value,unsigned int size) {for(unsigned int i=0;i<size;++i) p.push_back(static_cast<std::uint8_t>(value>>(8*i)));}
net::Packet packet(std::uint16_t op) {net::Packet p;put(p,op,2);put(p,9901,4);return p;}
constexpr std::uint64_t item_uid=0x7777000000000d01ULL;
std::uint32_t made() {return pack_world_time(std::chrono::sys_days{std::chrono::year{2024}/1/1});}
void item_fields(net::Packet& p,std::uint64_t uid,bool position,std::uint8_t slot=0) {put(p,uid,8);put(p,5001,4);if(position) p.insert(p.end(),{2,slot});p.insert(p.end(),{5,1,3});put(p,100,2);p.insert(p.end(),{1,2,3,4,5,6});const std::string craft="01020304050607080903";p.insert(p.end(),craft.begin(),craft.end());p.push_back(0);}
net::Packet receipt(std::uint16_t op,std::uint8_t source,std::uint8_t slot,std::uint64_t uid) {auto p=packet(op);p.insert(p.end(),{source,0,slot});item_fields(p,uid,false);put(p,made(),4);p.push_back('U');return p;}
net::Packet purchase(std::uint32_t cost,std::uint64_t uid,std::uint8_t slot=0) {auto p=packet(0xe02);std::string code="owner_purchase";code.resize(21,0);p.insert(p.end(),code.begin(),code.end());put(p,cost,4);put(p,made(),4);p.insert(p.end(),{'U',1});item_fields(p,uid,true,slot);return p;}
net::Packet point(std::uint16_t map) {auto p=packet(0xd02);p.push_back(0);put(p,map,2);for(auto bits:{0x3f800000U,0x40000000U,0x40400000U}) put(p,bits,4);return p;}
net::Packet market(std::uint32_t id) {auto p=packet(0x61a);p.push_back(1);put(p,id,4);return p;}
net::Packet quest(std::uint16_t id) {auto p=packet(0xa01);put(p,id,2);put(p,10,2);return p;}
net::Packet skill(std::uint16_t id,std::uint16_t points) {auto p=packet(0x801);put(p,points,2);put(p,id,2);p.push_back(1);return p;}
std::string read(const std::filesystem::path& path) {std::ifstream file(path,std::ios::binary);return {std::istreambuf_iterator<char>(file),{}};}
